inherit ROOM; void create(){ set("short","悬崖"); set("long","岩壁在这里收得很窄，上下都得靠手脚攀爬，可以试著向上或向下攀爬(climb up/down)。\n"); set("map/area","老松林"); set("map/layer","谷壁"); setup(); } void init(){ add_action("do_climb","climb"); } int do_climb(string arg){ if(arg=="up"){ this_player()->move(__DIR__"cliffdown"); return 1;} if(arg=="down"){ this_player()->move(__DIR__"epath3"); return 1;} return notify_fail("你要往上还是往下爬？\n"); }